import pandas as pd,numpy as np,os
from scipy.stats import spearmanr
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for a in A:
 p='../persistent/stock_data/'+a+'.csv'
 if os.path.exists(p):
  d=pd.read_csv(p);d.date=pd.to_datetime(d.date);d=d[d.date<='2029-04-18'].set_index('date').sort_index();D[a]=d.close
px=pd.concat(D,axis=1).sort_index(); ret=px.pct_change()
# Relative-strength acceleration: recent 5d return relative to own 20d trend,
# then cross-sectionally demeaned; all inputs shifted one completed day.
raw=ret.rolling(5,min_periods=5).sum()-ret.rolling(20,min_periods=20).sum()/4
f=raw.shift(1)
for h in [1,3,5,10]:
 fr=px.pct_change(h).shift(-h); vals=[]; turnovers=[]
 for dt in f.index:
  z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(z)>=8:
   vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
   # signal rank turnover against prior date, measured on common names
   if dt in f.index and f.index.get_loc(dt)>0:
    prev=f.iloc[f.index.get_loc(dt)-1]
    q=pd.concat([f.loc[dt],prev],axis=1).dropna()
    turnovers.append(np.mean((q.iloc[:,0].rank(pct=True)-q.iloc[:,1].rank(pct=True)).abs()))
 x=np.array(vals);print('h',h,'dates',len(x),'avgN',round(np.mean([len(pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()) for dt in f.index if len(pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna())>=8]),2),'IC',round(np.nanmean(x),6),'ICIR',round(np.nanmean(x)/np.nanstd(x,ddof=1),6),'hit',round(np.mean(x>0),4),'turn',round(np.nanmean(turnovers),4))
# regime split recent and pre-2027 for daily
fr=px.pct_change(1).shift(-1); vals=[]
for dt in f.index:
 z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
 if len(z)>=8: vals.append((dt,spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic))
for name,sel in [('all',lambda d:True),('pre2027',lambda d:d<'2027-01-01'),('2027+',lambda d:d>='2027-01-01')]:
 x=np.array([v for d,v in vals if sel(d)]);print(name,'dates',len(x),'IC',round(x.mean(),6),'ICIR',round(x.mean()/x.std(ddof=1),6))
print('instruments',len(D),'rows',len(px))

