import numpy as np,pandas as pd,os
from scipy.stats import spearmanr
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; D={}
for s in A:
 p='../persistent/stock_data/'+s+'.csv'
 if os.path.exists(p):
  d=pd.read_csv(p); d.date=pd.to_datetime(d.date); D[s]=d.set_index('date').sort_index().close
P=pd.concat(D,axis=1).sort_index().ffill(); R=P.pct_change(); M=R.mean(axis=1)
# Cross-sectional dispersion gate: residual reversal is active only when trailing 10d dispersion is above its trailing 120d median.
def sig(i,hold=3):
 r=R.iloc[:i+1]; disp=r.tail(10).std(axis=1).mean()
 hist=r.iloc[max(0,i-119):i+1].rolling(10).std().mean(axis=1).dropna()
 if len(hist)<20 or disp <= hist.median(): return pd.Series(np.nan,index=A)
 out={}
 for s in A:
  rr=r[s].tail(30); mm=M.iloc[:i+1].tail(30); beta=rr.cov(mm)/(mm.var()+1e-8)
  res=rr-beta*mm
  out[s]=-res.tail(hold).sum()/(rr.std()+1e-6)
 return pd.Series(out)
for hold in [3,5,10]:
 vals=[]; ns=[]; active=0; turns=[]; prev=None
 for i in range(130,len(P)-1):
  f=sig(i,hold); 
  if f.notna().sum()==0: continue
  active+=1; y=R.iloc[i+1]; z=pd.concat([f,y],axis=1).dropna()
  if len(z)>=8:
   vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic); ns.append(len(z)); q=f.rank(pct=True); turns.append(np.abs(q-(prev if prev is not None else q)).mean()); prev=q
 x=np.array(vals); print('hold',hold,'dates',len(x),'active',active,'avgN',round(np.mean(ns),2),'IC',round(x.mean(),6),'dailyICIR',round(x.mean()/x.std(ddof=1),6),'hit',round(np.mean(x>0),4),'turn',round(np.mean(turns),4))
 # regime split
 for name,lo,hi in [('early',130, len(P)//2),('late',len(P)//2,len(P))]:
  a=[]
  for i in range(max(130,lo),min(len(P)-1,hi)):
   f=sig(i,hold); y=R.iloc[i+1]; z=pd.concat([f,y],axis=1).dropna()
   if len(z)>=8:a.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
  print(name,'n',len(a),'ic',round(np.mean(a),6) if a else None)

