for h,a in rows.items():
 a=np.asarray(a);print('horizon',h,'n',len(a),'IC',round(float(np.nanmean(a)),6),'ICIR',round(float(np.nanmean(a)/np.nanstd(a,ddof=1)),6),'hit',round(float(np.mean(a>0)),4))
