U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def get(s):
 for fn in (get_stock_daily_data,get_index_daily_data):
  try:
   x=fn(s,days=6000)
   if x is not None and len(x)>200:return x
  except Exception: pass
raw={s:get(s) for s in U}; raw={s:x for s,x in raw.items() if x is not None}
p=pd.concat({s:x.set_index('date')['close'] for s,x in raw.items()},axis=1).sort_index()
r=np.log(p).diff(); eff=r.rolling(20).sum()/r.abs().rolling(20).sum()
vr=r.rolling(10).std()/r.rolling(60).std()
# Continuous low-volatility emphasis, cross-sectional and lagged one session.
compress=(1-vr).clip(-2,2)
f=(-eff.rank(axis=1,pct=True))*compress.rank(axis=1,pct=True)
f=f.shift(1)
rows=[]
for d in f.index:
