q=z[z.h==20].set_index('date')
print('assets',len(raw),'coverage',round(f.loc['2029':'2034-02-03'].notna().mean().mean(),4),'active_date_fraction',round(f.notna().any(axis=1).mean(),4))
print('annual20'); print(q.groupby(q.index.year).ic.agg(['count','mean']).tail(8).to_string())
