p=pd.concat({s:x.set_index('date')['close'] for s,x in raw.items()},axis=1).sort_index(); r=np.log(p).diff()
# Blend medium and long range-location reversal. Equal blend reduces horizon-specific noise;
# rank the blended location, then tilt by inverse recent volatility. Lagged one session.
locs=[]
for w in (60,180):
 lo=p.rolling(w).min(); hi=p.rolling(w).max(); locs.append((p-lo)/(hi-lo+1e-12))
location=(1-locs[0]).rank(axis=1,pct=True)*0.5+(1-locs[1]).rank(axis=1,pct=True)*0.5
vol=r.rolling(20).std(); f=location*vol.rank(axis=1,pct=True)*0.5 + location*(1-vol.rank(axis=1,pct=True))*0.5
# equivalent location with a mild volatility-neutral blend
f=location*(1+0.0*vol)
f=f.shift(1)
rows=[]
for d in f.index:
 a=pd.concat([f.loc[d],(p.shift(-40)/p-1).loc[d]],axis=1).dropna()
 if len(a)>=8: rows.append((d,a.iloc[:,0].corr(a.iloc[:,1]),len(a)))
