import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data,get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 d=get_stock_daily_data(s,4000)
 if d is None or len(d)<100: d=get_index_daily_data(s,4000)
 D[s]=d
prices=pd.concat({s:d.set_index('date')['close'] for s,d in D.items() if d is not None},axis=1).sort_index(); r=np.log(prices).diff(); rows=[]
for t in prices.index:
 pos=prices.index.get_loc(t)
 if pos+10>=len(prices.index): continue
 past=r.loc[:t].tail(10).sum(); vol=r.loc[:t].tail(20).std()*np.sqrt(252); cs=past.dropna()
 if len(cs)<8: continue
 resid=past-past.median(); dispersion=cs.std(); hist=[]
 for j in range(max(20,pos-120),pos+1):
  rr=r.iloc[max(0,j-9):j+1].sum(); x=rr.dropna()
  if len(x)>=8: hist.append(x.std())
 if len(hist)<20: continue
 gate=1.0 if dispersion>=np.nanmedian(hist) else .35; f=(-resid/(vol+1e-8))*gate; fw=np.log(prices.iloc[pos+10]/prices.iloc[pos]); z=pd.concat([f.rename('f'),fw.rename('fw')],axis=1).dropna()
 if len(z)>=8: rows.append((t,z.f.corr(z.fw),len(z),gate))
out=pd.DataFrame(rows,columns=['date','ic','n','gate']).set_index('date')
print('dates',len(out),'mean_n',out.n.mean(),'coverage',out.n.mean()/15,'meanIC',out.ic.mean(),'ICIR',out.ic.mean()/out.ic.std(),'hit',(out.ic>0).mean(),'turnover_proxy',out.ic.diff().abs().mean(),'gates',out.gate.value_counts().to_dict())
for a,b in [('2020','2025-12-31'),('2026','2029-12-31'),('2030','2032-12-31'),('2033','2034-12-31')]:
 x=out.loc[a:b,'ic']; print(a,b,len(x),x.mean(),x.mean()/x.std() if x.std()>0 else np.nan)
out.to_csv('../persistent/miner_3_20340901_residual_reversal_ic.csv')

import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_index_daily_data,get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; D={}
for s in U:
 d=get_stock_daily_data(s,2500)
 if d is None or len(d)<100:d=get_index_daily_data(s,2500)
 D[s]=d
p=pd.concat({s:d.set_index('date')['close'] for s,d in D.items() if d is not None},axis=1).sort_index(); r=np.log(p).diff(); ret=r.rolling(10).sum(); vol=r.rolling(20).std()*np.sqrt(252); rows=[]
# dispersion history precomputed
csdisp=ret.std(axis=1); med=csdisp.rolling(120,min_periods=20).median()
for i in range(120,len(p)-10):
 f=-(ret.iloc[i]-ret.iloc[i].median())/(vol.iloc[i]+1e-8); gate=1.0 if csdisp.iloc[i]>=med.iloc[i] else .35; f*=gate; fw=np.log(p.iloc[i+10]/p.iloc[i]); z=pd.concat([f.rename('f'),fw.rename('fw')],axis=1).dropna()
 if len(z)>=8:rows.append((p.index[i],z.f.corr(z.fw),len(z),gate))
o=pd.DataFrame(rows,columns=['date','ic','n','gate']).set_index('date'); print('dates',len(o),'mean_n',o.n.mean(),'coverage',o.n.mean()/15,'meanIC',o.ic.mean(),'ICIR',o.ic.mean()/o.ic.std(),'hit',(o.ic>0).mean(),'turnover_proxy',o.ic.diff().abs().mean());
for a,b in [('2020','2025-12-31'),('2026','2029-12-31'),('2030','2032-12-31'),('2033','2034-12-31')]:
 x=o.loc[a:b,'ic'];print(a,b,len(x),x.mean(),x.mean()/x.std() if x.std()>0 else np.nan)
o.to_csv('../persistent/miner_3_20340901_residual_reversal_ic.csv')

import pandas as pd,numpy as np,os
from scipy.stats import spearmanr
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; p={}
for a in A:
 f='../persistent/stock_data/'+a+'.csv'
 if os.path.exists(f): p[a]=pd.read_csv(f,parse_dates=['date']).set_index('date').close
P=pd.DataFrame(p).sort_index(); r=P.pct_change();
# medium trend: 60d return excluding latest 5d, volatility normalized, lagged
sig=(P.shift(5)/P.shift(65)-1)/(r.rolling(60,min_periods=40).std()*np.sqrt(60)+1e-9); sig=sig.shift(1)
for h in [1,5,10,20]:
 f=P.pct_change(h).shift(-h); vals=[]; ns=[]; dates=[]
 for d in sig.index:
  x,y=sig.loc[d],f.loc[d]; ok=x.notna()&y.notna()
  if ok.sum()>=8: vals.append(spearmanr(x[ok],y[ok]).statistic);ns.append(ok.sum());dates.append(d)
 z=pd.Series(vals,index=dates); print('h',h,'dates',len(z),'n',np.mean(ns),'IC %.6f ICIR %.6f hit %.3f'%(z.mean(),z.mean()/z.std(ddof=1),(z>0).mean()))
 print('recent',z.loc['2026':].mean(),z.loc['2026':].mean()/z.loc['2026':].std(ddof=1))
print('turnover',sig.rank(axis=1,pct=True).diff().abs().mean().mean())
out=sig.reset_index().melt(id_vars='date',var_name='symbol',value_name='signal').dropna();out.to_csv('../persistent/miner_3_20340915_medium_trend_signal.csv',index=False)

import pandas as pd,numpy as np,os
from scipy.stats import spearmanr
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
p={}
for a in A:
 f='../persistent/stock_data/'+a+'.csv'
 if os.path.exists(f): p[a]=pd.read_csv(f,parse_dates=['date']).set_index('date').close
P=pd.DataFrame(p).sort_index(); r=P.pct_change()
v=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).set_index('date')['close'].reindex(P.index).ffill()
# one-day-lagged 5d cross-sectional reversal, amplified when VIX is falling (rebound regime)
vixfall=(v.shift(1)<v.shift(6)).astype(float)
base=-P.pct_change(5).shift(1)
sig=base*(0.5+vixfall)
fw=P.pct_change().shift(-1); rows=[]
for d in sig.index:
 x,y=sig.loc[d],fw.loc[d]; ok=x.notna()&y.notna()
 if ok.sum()>=8: rows.append((d,spearmanr(x[ok],y[ok]).statistic,ok.sum()))
o=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date');
print('factor macro-conditioned 5d reversal');print('dates',len(o),'mean_n',o.n.mean(),'coverage',o.n.mean()/15,'IC %.6f ICIR %.6f hit %.3f'%(o.ic.mean(),o.ic.mean()/o.ic.std(ddof=1),(o.ic>0).mean()))
for a,b in [('2020','2025-12-31'),('2026','2029-12-31'),('2030','2032-12-31'),('2033','2034-12-31')]:
 z=o.loc[a:b].ic;print(a,b,'dates',len(z),'IC %.6f ICIR %.6f'%(z.mean(),z.mean()/z.std(ddof=1)))
for h in [5,10,20]:
 fw=P.pct_change(h).shift(-h); q=[]
 for d in sig.index:
  x,y=sig.loc[d],fw.loc[d];ok=x.notna()&y.notna()
  if ok.sum()>=8:q.append(spearmanr(x[ok],y[ok]).statistic)
 q=pd.Series(q);print('decay',h,'IC %.6f ICIR %.6f'%(q.mean(),q.mean()/q.std(ddof=1)))
print('turnover',sig.rank(axis=1,pct=True).diff().abs().mean().mean())
out=sig.reset_index().melt(id_vars='date',var_name='symbol',value_name='signal').dropna();out.to_csv('../persistent/miner_3_20340929_macro_conditioned_reversal_signal.csv',index=False)

